class Solution {
  public int countQuadruplets(int[] nums) {
    int n = nums.length, count = 0;
    int[] diffs = new int[401]; // nums[d] - nums[c] for c > b, shifted by 100
    for (int b = n - 3; b >= 1; b--) {
      for (int d = b + 2; d < n; d++) diffs[nums[d] - nums[b + 1] + 100]++;
      for (int a = 0; a < b; a++) count += diffs[nums[a] + nums[b] + 100];
    }
    return count;
  }
}
